414	//  HBM bf16 ACTS buffer (Fork B). Carved from the FRONT of the workspace the
415	//  host already allocates (float[nCTA*total + nCTA]); Fork B does not use that
416	//  space for the eliminated 223 MB grad partials, so it is free real estate.
417	//  Reinterpreted as __nv_bfloat16. Total 80,546,592 bf16 (161 MB) << the 223 MB
418	//  workspace; 62 MB headroom. All regions row-major [rows x width].
419	//
420	//  Offsets are RUNTIME (depend on T = B*kSeq, B is a host arg), computed by
421	//  DecActs::bind. The struct holds base pointers per region.
422	// ════════════════════════════════════════════════════════════════════════
423	struct DecActs {
424	    // Per-layer linear INPUTS X (needed by dW = dY^T @ X):
425	    __nv_bfloat16* X_in[dec::kLayers];    // [T, d]    in_proj input (= layer input)
426	    __nv_bfloat16* X_ctx[dec::kLayers];   // [T, d]    out_proj input (attn context)
427	    __nv_bfloat16* X_x1[dec::kLayers];    // [T, d]    ff0 input (n1 output)
428	    __nv_bfloat16* X_gact[dec::kLayers];  // [T, dff]  ff2 input (gelu output)
429	    // Per-layer linear OUTPUT adjoints dY (needed by dW + bias db = Σ_t dY):
430	    __nv_bfloat16* dY_qkv[dec::kLayers];  // [T, 3d]   in_proj output adjoint
431	    __nv_bfloat16* dY_a[dec::kLayers];    // [T, d]    out_proj output adjoint
432	    __nv_bfloat16* dY_ff0[dec::kLayers];  // [T, dff]  ff0 output adjoint
433	    __nv_bfloat16* dY_ff2[dec::kLayers];  // [T, d]    ff2 output adjoint
434	    // Head (B rows — last position only):
435	    __nv_bfloat16* X_hn;                  // [B, d]    head input
436	    __nv_bfloat16* dY_logits;             // [B, V]    head output adjoint (dlogits)
437	    // Embedding-input adjoint (needed by tok/pos owner-scan):
438	    __nv_bfloat16* dh0;                   // [T, d]
439	};
