441	__device__ __forceinline__ DecActs dec_acts_bind(__nv_bfloat16* p, int T, int B) {
442	    DecActs a;
443	    int64_t off = 0;
444	    const int64_t Td = (int64_t)T * dec::kD;
445	    const int64_t T3d = (int64_t)T * 3 * dec::kD;
446	    const int64_t Tff = (int64_t)T * dec::kDff;
447	    for (int li = 0; li < dec::kLayers; ++li) {
448	        a.X_in[li]   = p + off; off += Td;
449	        a.X_ctx[li]  = p + off; off += Td;
450	        a.X_x1[li]   = p + off; off += Td;
451	        a.X_gact[li] = p + off; off += Tff;
452	        a.dY_qkv[li] = p + off; off += T3d;
453	        a.dY_a[li]   = p + off; off += Td;
454	        a.dY_ff0[li] = p + off; off += Tff;
455	        a.dY_ff2[li] = p + off; off += Td;
456	    }
457	    a.X_hn      = p + off; off += (int64_t)B * dec::kD;
458	    a.dY_logits = p + off; off += (int64_t)B * dec::kVocab;
459	    a.dh0       = p + off; off += Td;
460	    return a;
461	}
