463	// ════════════════════════════════════════════════════════════════════════
464	//  bf16 WEIGHT PRE-STAGE (reg-pressure campaign C1 + cp.async-ring blocker (a)).
465	//  The fwd/dX GEMMs' B operand was the fp32 params blob CONVERTED ON READ
466	//  (__float2bfloat16 inside the staging accessor). That conversion web is the
467	//  measured marginal register demand of the K-loop (the pure-bf16 dW path
468	//  allocates spill-free at the same accumulator width while the fp32-read
469	//  fwd/dX paths spill ~2.2 KB when isolated), and it is the documented blocker
470	//  (a) of the cp.async/TMA ring: an async copy cannot convert, so the dominant
471	//  operand could not stream. Fix: convert ONCE per step into a bf16 weight
472	//  cache carved from the workspace, and stage the GEMM B operand from the
473	//  cache. cache[i] = __float2bfloat16(params[i]) is the IDENTICAL deterministic
474	//  per-element rounding the on-read path performed -> every GEMM consumes
475	//  BIT-IDENTICAL operand values; numerics/parity/A-A-A are unchanged BY
476	//  CONSTRUCTION (pure caching of a pure function; no reorder, no reassociation).
477	//
478	//  Only the 8 per-layer GEMM weight matrices (in_w/out_w/ff0_w/ff2_w x layers)
479	//  are cached: they are the ONLY fp32->bf16 on-read GEMM operands (the head
480	//  runs scalar fp32 per the oracle; embeddings/biases/LN are scalar fp32; the
481	//  dW GEMM operands are bf16 acts already). All sizes derive from the layout
482	//  constants -- no problem-specific hardcoding; the bench layout scales it.
483	//
484	//  C1-T (RING): a SECOND section of the cache holds the same 8 matrices
485	//  TRANSPOSED (W^T [Kin,Nout]). The dX GEMM reads W transposed; from the
486	//  row-major cache that staging is a k-stride 2-byte gather, which no 4/8/16B
487	//  cp.async can express (the same structural shape as ring blocker (b)).
488	//  Staging dX's B operand from W^T instead makes its tile rows K-CONTIGUOUS,
489	//  so the cp.async double-buffered ring streams BOTH fwd and dX weight
490	//  operands. WT[r,c] == W-cache[c,r] bit-identically (same fp32 element, same
491	//  deterministic rounding, written by exactly one thread) -> operand values,
492	//  parity and A/A/A are unchanged by construction. Cost: the cache doubles
493	//  (1.57 MB at d=128, 101 MB at d=1024 -- workspace headroom verified at both).
494	// ════════════════════════════════════════════════════════════════════════
495	struct DecWBf {
496	    const __nv_bfloat16* in_w[dec::kLayers];    // [3d, d]  per layer
497	    const __nv_bfloat16* out_w[dec::kLayers];   // [d, d]   per layer
498	    const __nv_bfloat16* ff0_w[dec::kLayers];   // [dff, d] per layer
499	    const __nv_bfloat16* ff2_w[dec::kLayers];   // [d, dff] per layer
500	    // ── C1-T (RING section): the SAME four matrices stored TRANSPOSED, W^T
501	    //    [Kin, Nout] row-major. WT[r,c] == W-cache[c,r] BIT-IDENTICAL (the same
502	    //    __float2bfloat16 of the same fp32 element, stored twice). Purpose: the
503	    //    dX GEMM's B operand reads W TRANSPOSED (srcB(n=kin,k=out) = W[out,kin],
504	    //    a k-stride-Kin 2-byte gather the cp.async ring cannot stream — the same
505	    //    structural shape as ring blocker (b)). Staging from W^T instead makes
506	    //    the dX B-tile rows K-CONTIGUOUS (16B-chunkable), unblocking the ring on
507	    //    the dX path with UNCHANGED operand values → numerics/parity/A-A-A
508	    //    identical by construction. ──
509	    const __nv_bfloat16* in_wT[dec::kLayers];   // [d, 3d]  per layer
510	    const __nv_bfloat16* out_wT[dec::kLayers];  // [d, d]   per layer
511	    const __nv_bfloat16* ff0_wT[dec::kLayers];  // [d, dff] per layer
512	    const __nv_bfloat16* ff2_wT[dec::kLayers];  // [dff, d] per layer
513	};
514	constexpr int64_t kWbfInW        = (int64_t)3 * dec::kD * dec::kD;
515	constexpr int64_t kWbfOutW       = (int64_t)dec::kD * dec::kD;
516	constexpr int64_t kWbfFf0W       = (int64_t)dec::kDff * dec::kD;
517	constexpr int64_t kWbfFf2W       = (int64_t)dec::kD * dec::kDff;
518	constexpr int64_t kWbfLayerElems = kWbfInW + kWbfOutW + kWbfFf0W + kWbfFf2W;
519	constexpr int64_t kWbfTotalElems = (int64_t)dec::kLayers * kWbfLayerElems;
520	// Full cache: straight section [kWbfTotalElems] + transposed section (C1-T,
521	// same element count — every matrix size is a multiple of 8 so both sections
522	// and every per-matrix base stay 16B-aligned for the cp.async ring).
523	constexpr int64_t kWbfCacheElems = 2 * kWbfTotalElems;
524	// Workspace floats the cache occupies (bf16 elems -> float units, rounded up).
525	__host__ __device__ __forceinline__ int64_t dec_wbf_floats() {
526	    return (kWbfCacheElems + 1) / 2;
527	}
528	__device__ __forceinline__ DecWBf dec_wbf_bind(const __nv_bfloat16* c) {
529	    DecWBf wb;
530	    #pragma unroll
531	    for (int li = 0; li < dec::kLayers; ++li) {
532	        const __nv_bfloat16* b = c + (int64_t)li * kWbfLayerElems;
533	        wb.in_w[li]  = b;
534	        wb.out_w[li] = b + kWbfInW;
535	        wb.ff0_w[li] = b + kWbfInW + kWbfOutW;
536	        wb.ff2_w[li] = b + kWbfInW + kWbfOutW + kWbfFf0W;
537	        // transposed section (C1-T): same per-layer/per-matrix offsets, based
538	        // kWbfTotalElems further in (element counts identical per matrix).
539	        const __nv_bfloat16* t = b + kWbfTotalElems;
540	        wb.in_wT[li]  = t;
541	        wb.out_wT[li] = t + kWbfInW;
542	        wb.ff0_wT[li] = t + kWbfInW + kWbfOutW;
543	        wb.ff2_wT[li] = t + kWbfInW + kWbfOutW + kWbfFf0W;
544	    }
545	    return wb;
546	}
547	// Grid-strided fp32->bf16 convert of the 8 matrices into the cache. Element-
548	// owned (each cache index written by exactly one thread), no atomics ->
549	// deterministic. Caller fences with the existing grid barrier before any GEMM
550	// reads the cache (P0->B0; the SAM re-convert gets its own barrier). The
551	// kDecOffsets index of [in_w,out_w,ff0_w,ff2_w] for layer li is {2,4,10,12} +
552	// 12*li (the 12-tensors-per-layer stride of the generated layout -- the same
553	// indices dectc_build_dw_specs walks).
554	__device__ __forceinline__ void dectc_wbf_convert(
555	        const float* __restrict__ params, __nv_bfloat16* __restrict__ cache,
556	        int cta, int nCTA) {
557	    const int64_t stride = (int64_t)nCTA * blockDim.x;
558	    for (int64_t i = (int64_t)cta * blockDim.x + threadIdx.x;
559	         i < kWbfCacheElems; i += stride) {
560	        // Section split: [0, kWbfTotalElems) = straight copies; the tail is the
561	        // C1-T TRANSPOSED section (the dX ring's B operand). Both sections are
562	        // element-owned (one writer per cache index) -> deterministic.
563	        const bool   tr = (i >= kWbfTotalElems);
564	        const int64_t ii = tr ? (i - kWbfTotalElems) : i;
565	        const int   li = (int)(ii / kWbfLayerElems);
566	        const int64_t r = ii % kWbfLayerElems;
567	        int wi; int64_t off, nout, kin;
568	        if      (r < kWbfInW)                       { wi = 2;  off = r;                                  nout = 3 * dec::kD; kin = dec::kD;   }
569	        else if (r < kWbfInW + kWbfOutW)            { wi = 4;  off = r - kWbfInW;                        nout = dec::kD;     kin = dec::kD;   }
570	        else if (r < kWbfInW + kWbfOutW + kWbfFf0W) { wi = 10; off = r - kWbfInW - kWbfOutW;             nout = dec::kDff;   kin = dec::kD;   }
571	        else                                        { wi = 12; off = r - kWbfInW - kWbfOutW - kWbfFf0W;  nout = dec::kD;     kin = dec::kDff; }
572	        // straight: source element `off` of W [Nout,Kin]. transposed: `off` is
573	        // element (rr,cc) = (off/Nout, off%Nout) of W^T [Kin,Nout]; its source is
574	        // W[cc,rr] = element cc*Kin + rr — the SAME fp32 through the SAME
575	        // deterministic rounding, so WT[rr,cc] is bit-identical to W-cache[cc,rr].
576	        const int64_t src = tr ? ((off % nout) * kin + (off / nout)) : off;
577	        cache[i] = __float2bfloat16(params[(int64_t)kDecOffsets[wi + li * 12] + src]);
578	    }
579	}
