582	//  Canonical Major-K smem stager. The ss-wgmma operand smem tile (MN rows x
583	//  K=16 bf16) MUST be in the CUTLASS Major-K INTERLEAVE layout (wgmma.cuh):
584	//      idx(mn,k) = (k/8)*(MN*8) + mn*8 + (k%8)
585	//  This helper writes ONE such MN x 16 tile, pulling element (mn, k) from a
586	//  caller-provided accessor `src(mn, kbase + k)`. Routing the source axis
587	//  through the accessor is what lets the SAME wgmma issue (TransA=0/TransB=0,
588	//  the substrate-validated orientation) serve fwd / dX / dW: the staging loop
589	//  transposes physically; the engine never leaves the gated path.
590	//
591	//  Cooperative over `nthreads` threads starting at thread `t0` (a warpgroup).
592	// ════════════════════════════════════════════════════════════════════════
593	template <int MN, typename Src>
594	__device__ __forceinline__ void stage_kmajor_tile(
595	        __nv_bfloat16* smem_tile, int kbase, Src src, int t0, int nthreads) {
596	    // MN*16 elements, each thread strides.
597	    #pragma unroll 1
598	    for (int i = t0; i < MN * wgs::kWgmmaAtomK; i += nthreads) {
599	        const int mn = i / wgs::kWgmmaAtomK;
600	        const int k  = i % wgs::kWgmmaAtomK;
601	        const int dst = (k >> 3) * (MN * 8) + mn * 8 + (k & 7);
602	        smem_tile[dst] = src(mn, kbase + k);
603	    }
604	}
