1524	//    ff0(work) := X_x1 @ ff0_w^T ; (ff0+ff0_b)→ff0pre(bf16); gelu(ff0+ff0_b)→X_gact[li](bf16)
1525	//    ff2(work) := X_gact @ ff2_w^T ; r2=x1+ff2+ff2_b (work); n2(r2)→X_in[li+1]
1526	//                 (last layer: n2→finalin fp32, the head input)
1527	//  BIASES (in/out/ff0/ff2) are folded in fp32 at these points (the oracle adds
1528	//  them in fp32 after the bf16 matmul); LN β + head out_b were already applied.
1529	// ════════════════════════════════════════════════════════════════════════
1530	__device__ float dectc_forward_tile(
1531	        const DecWeights& w, const DecWBf& wb, int g0, int nrows, const DecActs& acts,
1532	        const DecTileScratch& sc, const int* __restrict__ tok_ids,
1533	        const int* __restrict__ tgt_ids,
1534	        __nv_bfloat16* sA, __nv_bfloat16* sB, float* red,
1535	        unsigned long long* pipeBars = nullptr) {
1536	    const int nsamp = nrows / dec::kSeq;
1537	    // ── Embedding: X_in[0][r] = tok[token_id[g0+r]] + pos[(g0+r)%S]. bf16. ──
1538	    for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1539	        const int r = idx / dec::kD, j = idx % dec::kD;
1540	        const int g = g0 + r;
1541	        const int tid = tok_ids[g];
1542	        const int sp = g % dec::kSeq;            // position within the sample
1543	        float v = w.tok[(int64_t)tid * dec::kD + j] + w.pos[(int64_t)sp * dec::kD + j];
1544	        acts.X_in[0][(int64_t)g * dec::kD + j] = __float2bfloat16(v);
1545	    }
1546	    __syncthreads();
1547	
1548	    for (int li = 0; li < dec::kLayers; ++li) {
1549	        const DecWeights::Layer& L = w.layer[li];
1550	        const __nv_bfloat16* Xin = acts.X_in[li] + (int64_t)g0 * dec::kD;        // [nrows,d]
1551	        // qkv = Xin @ in_w^T + in_b   (N=3d, K=d). bf16 → scratch.qkv[li].
1552	        dectc_gemm_fwd<SG_TUNED_TILE_N>(Xin, wb.in_w[li], sc.qkv[li], dec::kD, 3 * dec::kD, sA, sB, pipeBars);
1553	        __syncthreads();
1554	        // add in_b (the fwd GEMM did W only; bias folded in scalar here for qkv —
1555	        // matches the bf16-faithful oracle qkv = bf(x_in @ bf(in_w)^T + in_b)).
1556	        for (int idx = threadIdx.x; idx < nrows * 3 * dec::kD; idx += blockDim.x) {
1557	            const int j = idx % (3 * dec::kD);
1558	            float v = __bfloat162float(sc.qkv[li][idx]) + L.in_b[j];
1559	            sc.qkv[li][idx] = __float2bfloat16(v);
1560	        }
1561	        __syncthreads();
1562	        // attention → ctx (work fp32) + attn[li] weights.
1563	        dectc_attn_fwd_tile(sc.qkv[li], nrows, sc.work, sc.attn[li]);
1564	        // ctx bf16 → X_ctx[li] (out_proj input + its dW operand).
1565	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1566	            const int r = idx / dec::kD, j = idx % dec::kD;
1567	            acts.X_ctx[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.work[(int64_t)r * dec::kD + j]);
1568	        }
1569	        __syncthreads();
1570	        // a = X_ctx @ out_w^T (+ out_b)  (N=d, K=d). fp32 → work.
1571	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_ctx[li] + (int64_t)g0 * dec::kD, wb.out_w[li],
1572	                                            sc.work, dec::kD, dec::kD, sA, sB, pipeBars);
1573	        __syncthreads();
1574	        // r1 = Xin + a + out_b → work (fp32). out_b folded here (the GEMM did W only)
1575	        // — matches the oracle a = ctx_b @ out_w^T + out_b kept fp32 through r1.
1576	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1577	            const int r = idx / dec::kD, j = idx % dec::kD;
1578	            sc.work[(int64_t)r * dec::kD + j] += __bfloat162float(Xin[(int64_t)r * dec::kD + j]) + L.out_b[j];
1579	        }
1580	        __syncthreads();
1581	        // n1(r1) → x1 (fp32) + caches[li]; then bf16 → X_x1[li] (ff0 input + dW operand).
1582	        dectc_ln_fwd_tile(sc.work, L.n1_w, L.n1_b, nrows, sc.x1, sc.n1x[li], sc.n1i[li], red);
1583	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1584	            const int r = idx / dec::kD, j = idx % dec::kD;
1585	            acts.X_x1[li][(int64_t)(g0 + r) * dec::kD + j] = __float2bfloat16(sc.x1[(int64_t)r * dec::kD + j]);
1586	        }
1587	        __syncthreads();
1588	        // ff0 = X_x1 @ ff0_w^T (+ ff0_b)  (N=dff, K=d). fp32 → work; (pre+b) bf16 →
1589	        // ff0pre; gelu(pre+b) → X_gact[li] (bf16, ff2 input + dW operand). ff0_b folded
1590	        // into pre (fp32) — matches the oracle ff0pre=bf(ff0+b), gact=bf(gelu(ff0+b)).
1591	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_x1[li] + (int64_t)g0 * dec::kD, wb.ff0_w[li],
1592	                                            sc.work, dec::kD, dec::kDff, sA, sB, pipeBars);
1593	        __syncthreads();
1594	        for (int idx = threadIdx.x; idx < nrows * dec::kDff; idx += blockDim.x) {
1595	            const int r = idx / dec::kDff, j = idx % dec::kDff;
1596	            float pre = sc.work[(int64_t)r * dec::kDff + j] + L.ff0_b[j];
1597	            sc.ff0pre[li][(int64_t)r * dec::kDff + j] = __float2bfloat16(pre);
1598	            acts.X_gact[li][(int64_t)(g0 + r) * dec::kDff + j] = __float2bfloat16(dec_gelu(pre));
1599	        }
1600	        __syncthreads();
1601	        // ff2 = X_gact @ ff2_w^T (+ ff2_b) (N=d, K=dff). fp32 → work.
1602	        dectc_gemm_fwd_f32<SG_TUNED_TILE_N>(acts.X_gact[li] + (int64_t)g0 * dec::kDff, wb.ff2_w[li],
1603	                                            sc.work, dec::kDff, dec::kD, sA, sB, pipeBars);
1604	        __syncthreads();
1605	        // r2 = x1 + ff2 + ff2_b → work (fp32). x1 lives in the dedicated fp32 buffer
1606	        // (no bf16 round). ff2_b folded here — matches the oracle r2 = x1 + (ff2 + ff2_b).
1607	        for (int idx = threadIdx.x; idx < nrows * dec::kD; idx += blockDim.x) {
1608	            const int r = idx / dec::kD, j = idx % dec::kD;
1609	            sc.work[(int64_t)r * dec::kD + j] += sc.x1[(int64_t)r * dec::kD + j] + L.ff2_b[j];
1610	        }
1611	        __syncthreads();
1612	        if (li + 1 < dec::kLayers) {
1613	            // n2(r2) → finalin (fp32 reused) + n2 caches[li]; bf16 → X_in[li+1].
1614	            dectc_ln_fwd_tile(sc.work, L.n2_w, L.n2_b, nrows, sc.finalin, sc.n2x[li], sc.n2i[li], red);

693	template <int N, int ScaleD, int TransA, int TransB>
694	__device__ __forceinline__ void wgmma_m64nNk16_bf16(
695	    WgmmaAccum<N>& acc, SmemDesc descA, SmemDesc descB
696	) {
697	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
698	    static_assert(N == 8 || N == 16 || N == 32 || N == 64 || N == 96 ||
699	                  N == 128,
700	                  "wgmma N must be one of {8,16,32,64,96,128} (bf16 atoms "
701	                  "selected by DESIGN §3); add the overload for other legal N");
702	#if (SG_TUNED_GEMM_ENGINE == 1)
703	    // Production is always TransA=TransB=0 (Major::K,Major::K); the CuTe atom
704	    // template binds that. Assert so a non-(0,0) caller is caught.
705	    static_assert(TransA == 0 && TransB == 0,
706	                  "SG_TUNED_GEMM_ENGINE=1 supports only Major-K/Major-K "
707	                  "(TransA=TransB=0), the production orientation.");
708	    cute_wgmma_issue<N, ScaleD>(acc, descA.desc, descB.desc);
709	#else
710	    if constexpr (N == 8)   wgmma_issue_n8  <ScaleD, TransA, TransB>(acc, descA.desc, descB.desc);
711	    else if constexpr (N == 16)  wgmma_issue_n16 <ScaleD, TransA, TransB>(acc, descA.desc, descB.desc);
712	    else if constexpr (N == 32)  wgmma_issue_n32 <ScaleD, TransA, TransB>(acc, descA.desc, descB.desc);
713	    else if constexpr (N == 64)  wgmma_issue_n64 <ScaleD, TransA, TransB>(acc, descA.desc, descB.desc);
714	    else if constexpr (N == 96)  wgmma_issue_n96 <ScaleD, TransA, TransB>(acc, descA.desc, descB.desc);
715	    else if constexpr (N == 128) wgmma_issue_n128<ScaleD, TransA, TransB>(acc, descA.desc, descB.desc);
716	#endif
717	#else
718	    (void)acc; (void)descA; (void)descB;
719	#endif
